# Regenerates docs/MAPPING-REVIEW.md from src/config/law-mapping.json (no outside data). usage: python3 scripts/concord/review-lists.py [--date YYYY-MM-DD]
import json, re, random, sys, collections
DATE = sys.argv[sys.argv.index("--date") + 1] if "--date" in sys.argv else "2026-10-31"
rows = json.load(open("src/config/law-mapping.json", encoding="utf8"))["rows"]
LABEL = {"ipc": "IPC", "crpc": "CrPC", "evidence": "Evidence Act", "bns": "BNS", "bnss": "BNSS", "bsa": "BSA"}
STOP = set("of the and or for in to a an by with under any it its is are as on at from be shall".split())
toks = lambda t: {w for w in re.findall(r"[a-z]{3,}", (t or "").lower()) if w not in STOP}
def ov(a, b):
    x, y = toks(a), toks(b); return len(x & y) / max(1, min(len(x), len(y))) if x and y else None
esc = lambda s: str(s).replace("|", "/")[:90]
sec = lambda law, n: f"{LABEL[law]} s.{n}"
nohead = lambda t: not t or t.startswith("(no heading")
conf = [r for r in rows if r.get("pairing_confirmed")]
both = [r for r in conf if r["old_text_in_data"] and r["new_text_in_data"]]
passed = [r for r in both if r["linkable"]]; failed = [r for r in both if not r["linkable"]]
missing = [r for r in conf if not (r["old_text_in_data"] and r["new_text_in_data"])]
def why(r):
    if nohead(r["old_title"]) and nohead(r["new_title"]): return "no heading in our data for either section"
    if nohead(r["old_title"]): return "no heading in our data for the old section"
    if nohead(r["new_title"]): return "no heading in our data for the new section"
    o = ov(r["old_title"], r["new_title"]); return f"low title overlap ({round(100 * (o or 0))}% of the shorter title's words shared)"
out = [f"# Section mapping: rows for review ({DATE})", "",
 "Source of every pairing: the Government's NCRB/MHA correspondence tables and the CAPT Bhopal tables; a row counts as *pairing confirmed* only when both agree. Titles are our own data's headings. Generated by `scripts/concord/review-lists.py` from `src/config/law-mapping.json`; nothing here comes from memory.", "",
 f"- Rows in the file: {len(rows)}. Pairing confirmed by both documents: {len(conf)}. Of these both sections are in our data (not garbled): {len(both)}. Title check passed (linkable): {len(passed)}. Title check failed: {len(failed)}. One section missing from our data: {len(missing)}.",
 f"- Linkable in the whole file: {sum(1 for r in rows if r.get('linkable'))} ({sum(1 for r in rows if r.get('linkable') and not r.get('pairing_confirmed'))} of them are earlier hand-checked rows that the two documents do not both confirm; one confirmed, linkable row keeps the status it had before and is not `verified`).",
 f"- Strictly `verified` (both documents agree, both sections in our data, titles correspond): {sum(1 for r in rows if r['status'] == 'verified')}.", "",
 f"## (a) The {len(failed)} rows that fail the title check (both sections are in our data, both documents agree on the pairing)", "",
 "| Old section | Old title | New section | New title | Reason |", "|---|---|---|---|---|"]
for r in failed: out.append(f"| {sec(r['old_law'], r['old_section'])} | {esc(r['old_title'])} | {sec(r['new_law'], r['new_section'])} | {esc(r['new_title'])} | {why(r)} |")
random.seed(20261030); sample = random.sample(passed, min(40, len(passed)))
out += ["", f"## (b) A random sample of 40 of the {len(passed)} that pass (seed 20261030)", "", "| Old section | Old title | New section | New title | Overlap / shared words |", "|---|---|---|---|---|"]
for r in sample:
    o = ov(r["old_title"], r["new_title"]); sh = sorted(toks(r["old_title"]) & toks(r["new_title"]))
    out.append(f"| {sec(r['old_law'], r['old_section'])} | {esc(r['old_title'])} | {sec(r['new_law'], r['new_section'])} | {esc(r['new_title'])} | {'hand check' if o is None else str(round(100 * o)) + '% (' + ', '.join(sh) + ')'} |")
multi = collections.defaultdict(list)
for r in rows:
    multi[(r["old_law"], re.match(r"\d+[A-Za-z]*", str(r["old_section"])).group(0).upper())].append(r)
m = [(k, v) for k, v in multi.items() if len(v) > 1 or v[0].get("also_new_sections")]
out += ["", f"## (c) The {len(m)} old sections that map to more than one new section", "", "| Old section | Old title | New section | New title | Pairing | Text in our data (old / new) |", "|---|---|---|---|---|---|"]
yn = lambda b: "yes" if b else "no"
for _, v in sorted(m, key=lambda kv: (kv[0][0], int(re.match(r"\d+", kv[0][1]).group(0)), kv[0][1])):
    for r in v:
        out.append(f"| {sec(r['old_law'], r['old_section'])} | {esc(r['old_title'])} | {sec(r['new_law'], r['new_section'])} | {esc(r['new_title'])} | {'confirmed (both)' if r['pairing_confirmed'] else 'one document only (' + ','.join(r.get('tables', [])) + ')'} | {yn(r['old_text_in_data'])} / {yn(r['new_text_in_data'])} |")
        for a in r.get("also_new_sections", []):
            out.append(f"| {sec(r['old_law'], r['old_section'])} | {esc(r['old_title'])} | {LABEL[r['new_law']]} s.{a['new_section']} | {esc(a['new_title'])} | {'confirmed (both)' if a['pairing_confirmed'] else 'one document only (' + ','.join(a.get('tables', [])) + ')'} | {yn(r['old_text_in_data'])} / {yn(a['new_text_in_data'])} |")
open("docs/MAPPING-REVIEW.md", "w", encoding="utf8").write("\n".join(out) + "\n")
print(len(rows), len(conf), len(both), len(passed), len(failed), len(missing), len(m))
